from html import unescape
s=open('wheat_site.html').read();
for term in ['identifier','datasets','dataset']:
 i=0; print('\\n',term)
 while True:
  i=s.find(term,i)
  if i<0:break
  print(unescape(s[max(0,i-150):i+300]));i+=len(term)
PY"

/bin/bash -lc "python - <<'PY'
import xml.etree.ElementTree as ET
r=ET.parse('article.xml').getroot(); ns='{http://www.w3.org/1999/xlink}href'
for f in r.iter():
 if f.tag.endswith('fig'):
  lab=next((x for x in f if x.tag.endswith('label')),None)
  print('FIG', ''.join(lab.itertext()) if lab is not None else '?')
  for x in f.iter():
   if ns in x.attrib: print(x.tag,x.attrib[ns])
PY"

